"""
============================================================================
XAUUSD_Adaptive_Bot_V5 -- multi-timeframe CONFLUENCE research bot
                          (GOLD only, DEMO only, single self-contained file)
============================================================================

SINGLE-FILE BUILD.  cTrader embeds and executes only the main Python file of
a cBot, so this file inlines the entire V5 system: the shared detectors
(market structure, liquidity, supply/demand, order blocks, fair-value gaps,
regime, sessions, news, spread, sizing, guards) and every V5 module -- the
multi-timeframe market state, the group-capped confluence engine, structural
stops and targets, the ONE trade-management state machine that shadow and
real trades share, the six setup families, the shadow portfolios, statistical
learning, the active-trading-day research clock, persistence and reporting.

NO folders, NO package imports, NO third-party packages, NO network access,
NO self-modifying code.  Generated by build_v5_single_file.py -- edit the
modular source, then rebuild.

WHAT CHANGED FROM V4
  V4 entered on standalone signals (a liquidity sweep plus a reclaim was
  enough).  V5 requires a MANDATORY multi-timeframe sequence before a setup
  exists, then scores the remaining evidence with a correlation-aware
  confluence engine and still demands a minimum score.  Six genuinely
  different setup families are researched, and the ranking reports the family
  as well as the variant.  Shadow trades now run the same management as real
  trades, exit labels are truthful, R and MFE share one denominator, bid/ask
  handling is symmetric, and stale or gapped fills are refused.

ABSOLUTE RAILS (stricter than V4; there is no live switch anywhere)
  * DEMO-only ("LIVE ACCOUNT BLOCKED" + stop) and GOLD-only allowlist
  * one real position; broker-side SL+TP on every order; stops never widen
  * 0.25% max risk/trade, graduated slowly upward from 0.10% with evidence
  * 4 real trades/day maximum
  * 1.7% combined daily loss lock; 5% weekly drawdown lock
  * cooldown after 3 consecutive losses; volume always rounded DOWN
  * minimum volatility-based stop distance (no unrealistically tight stops)
  * no martingale, no grid, no averaging down, no recovery sizing
  * restarting never resets the guards or the research clock, and the clock
    counts ACTIVE TRADING DAYS, so weekends cost no research days

RESEARCH OUTPUT (in <home>/Documents/XAUUSD_Adaptive_Bot_V5/)
  research_state.json, shadow_trades.csv, real_trades.csv,
  rejected_setups.csv, strategy_rankings.csv, family_rankings.csv,
  daily_summary.csv, equity_history.csv, learning_log.csv,
  parameter_updates.csv, management_events.csv, suspect_trades.csv,
  stop_watch.csv, heartbeat.csv, daily_report_*.txt,
  final_report.txt / final_report.json

NEWS PROTECTION is schedule-based and MANUAL.  There is no live news feed in
this bot and none is claimed: maintain fomc_events / cpi_events in V5Config.

The final result is labelled "PROVISIONAL WINNER -- NOT AUTOMATICALLY READY
FOR LIVE TRADING."  No profitability is claimed.  This is a demo research
instrument, not a trading recommendation.
"""

