class SetupGrade(str, Enum):
    A_PLUS = "A+"
    A = "A"
    B = "B"
    NO_TRADE = "NO_TRADE"

    @staticmethod
    def from_score(score: float) -> "SetupGrade":
        if score >= 90:
            return SetupGrade.A_PLUS
        if score >= 80:
            return SetupGrade.A
        if score >= 70:
            return SetupGrade.B
        return SetupGrade.NO_TRADE


